d=Drawing(W,425)
nodes={'users':(150,350),'services':(325,350),'appliances':(0,230),'repair_requests':(225,195),'orders':(0,90),'order_items':(160,0),'parts':(325,90)}
edges=[('users','appliances','1 / client_id'),('users','repair_requests','0..1 / client, master'),('services','repair_requests','1 / service_id'),('appliances','repair_requests','0..1 / appliance_id'),('users','orders','0..1 / client_id'),('orders','order_items','1 / order_id'),('parts','order_items','1 / part_id')]
for a,b,label in edges:
    x,y=nodes[a];xx,yy=nodes[b]; x+=65;y+=28;xx+=65;yy+=28
    d.add(Line(x,y,xx,yy,strokeColor=colors.HexColor('#555555'),strokeWidth=.8))
    lx,ly=(x+xx)/2,(y+yy)/2+4
    if a=='appliances':lx,ly=138,253
    if a=='users' and b=='orders':lx,ly=48,190
    d.add(String(lx,ly,label,fontName='Times',fontSize=7,fillColor=colors.black))
for name,(x,y) in nodes.items():
    d.add(Rect(x,y,135,55,fillColor=colors.HexColor('#F3F3F3'),strokeColor=colors.black,strokeWidth=.8))
    d.add(String(x+8,y+35,name,fontName='TimesBold',fontSize=11))
    d.add(String(x+8,y+14,'PK id UUID',fontName='Times',fontSize=10))
